    @Test
    fun testDecodeV2ArrayFloats() {
        val doc = applyFixtureV2(WireCompatFixtures.SINGLE_DOC_V2_ARRAY_FLOATS_UPDATE_V2)
        val arr = doc.getArray("arr")
        assertEquals(5, arr.length)
        val values = arr.toArray()
        assertEquals(1.5, values[0])
        assertEquals(-2.7, (values[1] as Number).toDouble(), 0.0001)
        assertEquals(0, values[2])
        assertEquals(3.14159, (values[3] as Number).toDouble(), 0.00001)
        assertEquals(-0.001, (values[4] as Number).toDouble(), 0.0001)
    }

    @Test
    fun testDecodeV2ArrayLargeInts() {
        val doc = applyFixtureV2(WireCompatFixtures.SINGLE_DOC_V2_ARRAY_LARGE_INTS_UPDATE_V2)
        val arr = doc.getArray("arr")
        assertEquals(5, arr.length)
        val values = arr.toArray()
        assertEquals(0, values[0])
        assertEquals(-1, values[1])
        assertEquals(2147483647, values[2])
        // -2147483648 is written as float32 by yjs (tag 124), decoded as Double
        assertEquals(-2147483648.0, (values[3] as Number).toDouble(), 0.0)
        assertEquals(1000000, values[4])
    }

