        val doc = Doc()
        doc.clientID = WireCompatFixtures.SINGLE_DOC_V2_ARRAY_INTS_CLIENT_ID
        val arr = doc.getArray("arr")
        arr.push(listOf(1, 2, 3))
        val encoded = encodeStateAsUpdateV2(doc)
        val actual = toHex(encoded)
        val expected = WireCompatFixtures.SINGLE_DOC_V2_ARRAY_INTS_UPDATE_V2
        assertEquals(expected, actual, "V2 encode array_ints should match yjs")
    }

