    // ==========================================================================
    // V2 decode then V1 encode cross-check: state equivalence
    // ==========================================================================

    @Test
    fun testV2DecodeProducesEquivalentStateToV1() {
        // Decode both V1 and V2 array_ints, verify they produce the same state
        val docV1 = Doc()
        applyUpdate(docV1, hexToBytes(WireCompatFixtures.SINGLE_DOC_V1_ARRAY_INTS_UPDATE))
        val docV2 = applyFixtureV2(WireCompatFixtures.SINGLE_DOC_V2_ARRAY_INTS_UPDATE_V2)

        val arrV1 = docV1.getArray("arr")
        val arrV2 = docV2.getArray("arr")
        assertEquals(arrV1.toArray(), arrV2.toArray(),
            "V1 and V2 decode of array_ints should produce same state")
    }

    @Test
    fun testV2DecodeMapEquivalentToV1() {
        val docV1 = Doc()
        applyUpdate(docV1, hexToBytes(WireCompatFixtures.SINGLE_DOC_V1_MAP_STRINGS_UPDATE))
        val docV2 = applyFixtureV2(WireCompatFixtures.SINGLE_DOC_V2_MAP_STRINGS_UPDATE_V2)

        val mapV1 = docV1.getMap("map")
        val mapV2 = docV2.getMap("map")
        assertEquals(mapV1.get("key1"), mapV2.get("key1"))
        assertEquals(mapV1.get("key2"), mapV2.get("key2"))
    }

    @Test
    fun testV2DecodeTextEquivalentToV1() {
        val docV1 = Doc()
        applyUpdate(docV1, hexToBytes(WireCompatFixtures.SINGLE_DOC_V1_TEXT_SIMPLE_UPDATE))
        val docV2 = applyFixtureV2(WireCompatFixtures.SINGLE_DOC_V2_TEXT_SIMPLE_UPDATE_V2)

